// Trend detection settings. The sheet must be shared as "Anyone with the link can view" so its CSV export works.
return [{ json: {
  sheetId: '1OF-8A70aY5uX-vLbbayVuJ4Tn7AATgmiiSUedpBpMsQ',
  gid: 0,                 // gid of the Reviews tab (the number after gid= in the sheet URL)
  window: 4,              // trailing weeks used as the baseline
  zThresh: 3.5,           // z-score needed to flag a week
  minCount: 8,            // ...and at least this many negative reviews in that week
  lookbackWeeks: 12,      // only alert on flags in the last N weeks of data
  dashboardUrl: 'https://docs.google.com/spreadsheets/d/1OF-8A70aY5uX-vLbbayVuJ4Tn7AATgmiiSUedpBpMsQ/edit',
} }];

const cfg = $('Config').first().json;
const text = String($input.first().json.data);
const lines = text.split(/\r?\n/).filter(l => l.trim());
const head = lines[0].split(',').map(h => h.trim());
const col = n => head.indexOf(n);
const iDate = col('review_date'), iSent = col('sentiment'), iIssue = col('issue_category');
if (iDate < 0 || iSent < 0 || iIssue < 0) {
  throw new Error('The Reviews tab needs review_date, sentiment and issue_category columns (got: ' + head.join(', ') + ')');
}
// Negative reviews that have an issue category, bucketed into weeks counted from the earliest review.
const DAY = 86400000;
const neg = [];
for (const l of lines.slice(1)) {
  const c = l.split(',');
  if (c[iSent] === 'negative' && c[iIssue]) neg.push({ t: Date.parse(c[iDate] + 'T00:00:00Z'), issue: c[iIssue] });
}
const all = lines.slice(1).map(l => Date.parse(l.split(',')[iDate] + 'T00:00:00Z')).filter(t => !isNaN(t));
const t0 = Math.min(...all);
const nWeeks = Math.floor((Math.max(...all) - t0) / (7 * DAY)) + 1;
const counts = {};
for (const r of neg) {
  const w = Math.floor((r.t - t0) / (7 * DAY));
  (counts[r.issue] = counts[r.issue] || new Array(nWeeks).fill(0))[w] += 1;
}
// z-score against the trailing baseline; the spread is floored at sqrt(mean) (Poisson) so quiet issues do not spike on noise.
const alerts = [];
for (const [issue, x] of Object.entries(counts)) {
  for (let t = cfg.window; t < nWeeks; t++) {
    const base = x.slice(t - cfg.window, t);
    const mu = base.reduce((a, b) => a + b, 0) / base.length;
    const sample = Math.sqrt(base.reduce((a, b) => a + (b - mu) ** 2, 0) / (base.length - 1));
    const sd = Math.max(sample, Math.sqrt(Math.max(mu, 1)));
    const z = (x[t] - mu) / sd;
    if (z >= cfg.zThresh && x[t] >= cfg.minCount && t >= nWeeks - cfg.lookbackWeeks) {
      alerts.push({
        issue_category: issue,
        week_start: new Date(t0 + t * 7 * DAY).toISOString().slice(0, 10),
        count: x[t], previous_week: x[t - 1], wow_delta: x[t] - x[t - 1],
        baseline_mean: Number(mu.toFixed(2)), z: Number(z.toFixed(2)),
      });
    }
  }
}
alerts.sort((a, b) => b.z - a.z);
return [{ json: { reviews_read: lines.length - 1, negative_with_issue: neg.length, weeks: nWeeks, issues: Object.keys(counts).length, alerts } }];

const cfg = $('Config').first().json;
const d = $input.first().json;
const rows = d.alerts.map(a =>
  `- *${a.issue_category}*: ${a.count} negative reviews in the week of ${a.week_start} ` +
  `(baseline ${a.baseline_mean}, z ${a.z}, ${a.wow_delta >= 0 ? '+' : ''}${a.wow_delta} vs previous week)`);
const text = `*Negative review spike detected* (${d.alerts.length} issue${d.alerts.length === 1 ? '' : 's'})\n` +
  rows.join('\n') + `\n<${cfg.dashboardUrl}|Open the Review Insights Dashboard>`;
return [{ json: { ...d, slack_body: { text } } }];

const msg = $('Build Slack message').first().json;
const r = $input.first().json;
// A real Slack Incoming Webhook answers with exactly "ok"; anything else (an error, or an HTML page from a wrong URL) is a failure.
const body = typeof r.data === 'string' ? r.data.trim() : '';
const ok = !r.error && body === 'ok';
return [{ json: {
  alerts_found: msg.alerts.length,
  slack_status: ok ? 'sent' : 'failed',
  slack_error: ok ? null : (r.error ? JSON.stringify(r.error).slice(0, 200)
    : 'Slack did not answer "ok" (got: ' + body.slice(0, 60).replace(/\s+/g, ' ') + '). Check the webhook URL in the Post to Slack node.'),
  alerts: msg.alerts,
  message_preview: msg.slack_body.text,
} }];
